// ── NSID guards (F-Plan F2 archive, 2026-04-13) ──
// `sdk.app.command` / `sdk.app.query` enforce StrictCommandNSID / StrictQueryNSID.
// Legacy loose AssertCommandNSID / AssertQueryNSID archived to
// _archive/20-actors/magatama/sdk/magatama-host-sdk-legacy-nsid-assert-260413/.

type QueryAsCommandError<N extends string> = `NSID "${N}" is a lexicon query; register via app.query(...)`;
type ProcedureAsQueryError<N extends string> = `NSID "${N}" is a lexicon procedure; register via app.command(...)`;
type UnknownNsidError<N extends string> = `NSID "${N}" is not defined in 00-contracts/lexicons/. Create the lexicon JSON first (run bootstrap-app-lexicons.mjs or author by hand).`;

// Strict variants — the only supported form after F-Plan F2 archive (2026-04-13).
// `sdk.app.command` / `sdk.app.query` use these.
export type StrictCommandNSID<N extends string> = N extends KnownLexiconProcedureNSID ? N
  : N extends KnownLexiconQueryNSID ? QueryAsCommandError<N>
  : UnknownNsidError<N>;
export type StrictQueryNSID<N extends string> = N extends KnownLexiconQueryNSID ? N
  : N extends KnownLexiconProcedureNSID ? ProcedureAsQueryError<N>
  : UnknownNsidError<N>;

