export type LexiconNsid = keyof typeof LEXICON_NSID;

// ── nsid() tagged helper ──
// Enforces that the NSID exists at call site. Usage:
//   sdk.app.command(nsid("ai.gftd.apps.foo.bar"), handler) // typo → compile error

export function nsid<N extends LexiconNsid>(n: N): N {
	return n;
}

// ── Per-NSID input / output type maps (F-Plan F2, 2026-04-13) ──
// Handler can be declared as:
//   async (ctx, body) => {
//     const input = decodeJson<LexiconInput<"ai.gftd.apps.foo.bar">>(body);
//     ...
//     return {} as LexiconOutput<"ai.gftd.apps.foo.bar">;
//   }
